/*
  Roof

  We take it that wall plate has priority over the sloped front wall
  So the front wall is between the two side walls

  origin of the model is outer corner of side wall and front sloped wall

*/

SPAN = $SPAN; // span inside wall-to-wall inside
HEIGHT = $HEIGHT; // height of ridge of front wall from topplate of side wall
DEPTH = $DEPTH; // Depth from front wall to back (including wall depth)
WALL_DEPTH = 200; // of side and front wall
OVERHANG_LEFT = $OVERHANG_SIDE; // on x axis
OVERHANG_RIGHT = $OVERHANG_SIDE;
OVERHANG_FRONT = $OVERHANG_FRONTAL;
OVERHANG_BACK = $OVERHANG_FRONTAL;

PURLIN_SECTION_WIDTH = 100; // TODO: standard sizes
PURLIN_SECTION_HEIGHT = 200;
PURLIN_CTC_MAX =  1500;  // distance between centerlines of purlines

RAFTER_SECTION_WIDTH = 38;
RAFTER_SECTION_HEIGHT = 170;
RAFTER_KEEP_ZOFFSET = 40;
RAFTER_DISTANCE = 400;



//// CALCULATED PROPERTIES ////

ANGLE = Math.atan(HEIGHT/(SPAN/2)); // roof angle
ANGLE_DEG = toDeg(ANGLE);

//// MAIN ////

layer('context').color('red').dashed();


// Where to lay it on 
frontBottomRoofLineSlope = line([WALL_DEPTH,0,0],[SPAN/2,0,HEIGHT]);
frontBottomRoofLine = polyline([0,0,0], // with wall depth
                               frontBottomRoofLineSlope.start(), 
                               frontBottomRoofLineSlope.end())


centerline = line([SPAN/2,0,HEIGHT],[SPAN/2,0,0])
              .extend(1000, 'start')
              .dashed();

placeContour = rectBetween([0,0,0],[SPAN,DEPTH,0])
placeContourWallLeft = rectBetween([0,0,0],[-WALL_DEPTH, DEPTH, 0])
placeContourWallFront = rectBetween([0,0,0],[SPAN,WALL_DEPTH, 0])
placeContourWallBack = placeContourWallFront.copy().moveY(DEPTH-WALL_DEPTH)

layer('diagram').color('blue');

// First purlin on inside of wall
purlinWallLeftSection = rectBetween(
  [0,0,0],
  [-PURLIN_SECTION_WIDTH, 0, PURLIN_SECTION_HEIGHT]
).move(WALL_DEPTH)


purlinLineTop = frontBottomRoofLineSlope
  .copy()
  .align(purlinWallLeftSection, 'leftbottom', 'leftfronttop') // TODO: align with start/end
  .extendTo(centerline)


// fill in purlinLineTop with purlines using PURLIN_CTC_MAX
numMidPurlins = Math.round(purlinLineTop.length()/PURLIN_CTC_MAX) - 1;
purlinMidOffset = purlinLineTop.length()/(numMidPurlins + 1);


purlinsMidSections = collection();

for(p = 0; p < numMidPurlins; p++)
{
  purlinsMidSections.add(
    purlinWallLeftSection.copy()
      .move(purlinLineTop
      .direction()
      .normalize()
      .scale(purlinMidOffset*(p+1)))
      .name('purlinMidLeftSection' + (p+1))
  );
}


// top purlin AKA the ridge
ridgeSection = purlinWallLeftSection
                .copy()
                .align(
                  purlinLineTop.end(),
                  'frontcentertop',
                  'center'
                ).moveZ(-Math.tan(ANGLE)*PURLIN_SECTION_WIDTH/2)


// Rafters diagram

// Rafter bottom is purlinLineTop with "keep" (=cut) z offset

rafterBottomLineLeft = purlinLineTop
      .copy()
      .moveZ(-RAFTER_KEEP_ZOFFSET)
      .extendTo(
        line([0,0,0],[0,0,HEIGHT]).tmp()) // extend to outer wall line
       .extendTo(
        line([-OVERHANG_LEFT,0,-HEIGHT],[-OVERHANG_LEFT,0,HEIGHT]).tmp()
       )

rafterTopLineLeft = rafterBottomLineLeft.copy()
    .offset(-RAFTER_SECTION_HEIGHT)
    .extendTo(centerline)  
    .color('red');

rafterLongSection = rafterBottomLineLeft
                    .connect(rafterTopLineLeft)
                    .close() 

purlinSections = collection(
  purlinWallLeftSection, purlinsMidSections, ridgeSection)



//// 3D MODEL ////

layer('purlins').color('green');

purlinLength = DEPTH + OVERHANG_FRONT + OVERHANG_BACK;

purlinBeams = purlinSections.copy()
            .extrude(purlinLength, [0,1,0])
            .moveY(-OVERHANG_FRONT)
            .forEach((s,i) => s.name('purlin' + i))

// Blocking between purlins
purlinsBlocksFront =  frontBottomRoofLineSlope
                      .copy()
                      .offset(-PURLIN_SECTION_HEIGHT)
                      .extendTo(centerline)
                      .connect(frontBottomRoofLineSlope)
                      .extrude(PURLIN_SECTION_WIDTH, [0,1,0])
                      .cutoffBy(purlinBeams.first()) // NOTE: bit tricky here
                      .subtract(purlinBeams.first().copy().move(-PURLIN_SECTION_WIDTH,0,PURLIN_SECTION_WIDTH/2).tmp())
                      .cutoffBy(purlinBeams.last())
                      .subtract(purlinBeams.copy().moveZ(-1).tmp()) // Problem with directly on slope line)
                      .name('purlinsBlocksFront');
                      //.forEach((s,i) => s.name('purlinBlockFront' + i)); // Collection => Shape stub


purlinsBlocksBack = purlinsBlocksFront.copy().mirrorY(DEPTH/2);


layer('raftersLeft').color('brown')

numRafterBeamsDepth = Math.floor((
  DEPTH-2*RAFTER_SECTION_WIDTH)/(RAFTER_DISTANCE+RAFTER_SECTION_WIDTH)) + 1 // without the overhangs front and back

rafterBeams = rafterLongSection
                .extrude(RAFTER_SECTION_WIDTH, [0,1,0])
                .name('rafter')
                .moveY(-RAFTER_SECTION_WIDTH) // align to front of purlin
                .subtract(purlinBeams)
                .row(numRafterBeamsDepth, RAFTER_DISTANCE, [0,1,0]) // distance to 

// last front rafter/facia
rafterFaciaFront = rafterBeams.first().copy().moveY(-OVERHANG_FRONT+RAFTER_SECTION_WIDTH);
rafterBeams.add(rafterFaciaFront);

// last back rafter aligned with purlin
rafterBeams.add(rafterBeams.first().copy().mirrorY(DEPTH/2)).name('rafterBackFacade')
rafterBeams.add(rafterFaciaFront.copy().mirrorY(DEPTH/2)).name('rafterBackFacia')

// Right purlinsMidSections
layer('raftersRight').color('brown');
rafterBeamsRight = rafterBeams.copy().mirrorX(SPAN/2);
layer('purlinsRight').color('green')
purlinBeamsRight = purlinBeams.copy().mirrorX(SPAN/2);
collection(purlinsBlocksBack,purlinsBlocksFront).copy().mirrorX(SPAN/2);
